//! NSPasteboard snapshot / transient write / conditional restore.
//!
//! The paste flow borrows the general pasteboard for a few hundred
//! milliseconds:
//!
//! 1. [`snapshot`] copies every item and every type on the pasteboard
//!    into owned, `Send` Rust data (so it can cross threads / `.await`).
//! 2. [`write_transient`] writes the transcript as a single item tagged
//!    with the nspasteboard.org "transient" and "auto-generated" marker
//!    types, so clipboard managers (Maccy, Raycast, Paste, …) skip it and
//!    the user's history isn't polluted with every dictation.
//! 3. After ⌘V lands, [`restore_if_unchanged`] puts the snapshot back —
//!    but only if `changeCount` still equals the value recorded right
//!    after our write. If anything else wrote to the pasteboard in the
//!    meantime (the user copied something), we leave it alone.
//!
//! Every function here does synchronous AppKit work; callers run them on
//! a blocking thread (`spawn_blocking`), never on the async executor.

#![allow(unsafe_code)] // AppKit FFI via objc2; every block carries a SAFETY note

use objc2::rc::{autoreleasepool, Retained};
use objc2::runtime::ProtocolObject;
use objc2_app_kit::{
    NSPasteboard, NSPasteboardItem, NSPasteboardType, NSPasteboardTypeString, NSPasteboardWriting,
};
use objc2_foundation::{NSArray, NSData, NSString};

use super::InjectError;

/// nspasteboard.org marker: the item is short-lived, don't record it.
const TRANSIENT_TYPE: &str = "org.nspasteboard.TransientType";
/// nspasteboard.org marker: the item was written by software, not the user.
const AUTO_GENERATED_TYPE: &str = "org.nspasteboard.AutoGeneratedType";

/// One pasteboard item: every `(UTI, bytes)` representation it carried.
pub type SnapshotItem = Vec<(String, Vec<u8>)>;

/// Owned copy of the whole general pasteboard. An empty `items` vector
/// means the pasteboard was empty; restoring it clears the pasteboard.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct PasteboardSnapshot {
    pub items: Vec<SnapshotItem>,
}

/// Restore only when nobody else wrote to the pasteboard since our write.
///
/// `changeCount` increments on every `clearContents`, so equality means
/// the pasteboard still holds exactly what we put there.
pub fn should_restore(recorded_change_count: isize, current_change_count: isize) -> bool {
    recorded_change_count == current_change_count
}

fn general() -> Retained<NSPasteboard> {
    // SAFETY: `generalPasteboard` is a class method with no preconditions;
    // NSPasteboard is documented thread-safe for the general pasteboard.
    unsafe { NSPasteboard::generalPasteboard() }
}

/// Copy every item and type on the general pasteboard.
pub fn snapshot() -> PasteboardSnapshot {
    autoreleasepool(|_| {
        let pb = general();
        // SAFETY: `pasteboardItems` returns an optional retained array;
        // `None` (no items / pasteboard unavailable) is handled.
        let Some(items) = (unsafe { pb.pasteboardItems() }) else {
            return PasteboardSnapshot::default();
        };
        let mut out = Vec::with_capacity(items.len());
        for item in items.to_vec() {
            // SAFETY: `types` on a live NSPasteboardItem returns a retained
            // non-null array of NSString UTIs.
            let types = unsafe { item.types() };
            let mut reps: SnapshotItem = Vec::with_capacity(types.len());
            for ty in types.to_vec() {
                // SAFETY: `ty` is one of the item's own types; a `None`
                // result (provider failed to supply data) is skipped.
                if let Some(data) = unsafe { item.dataForType(ty) } {
                    reps.push((ty.to_string(), data.bytes().to_vec()));
                }
            }
            if !reps.is_empty() {
                out.push(reps);
            }
        }
        PasteboardSnapshot { items: out }
    })
}

/// Replace the pasteboard contents with `items`. Returns the post-write
/// `changeCount`.
fn write_items(items: Vec<Retained<NSPasteboardItem>>) -> Result<isize, InjectError> {
    let pb = general();
    // SAFETY: `clearContents` has no preconditions; it bumps changeCount.
    unsafe { pb.clearContents() };
    if !items.is_empty() {
        let objs: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = items
            .into_iter()
            .map(ProtocolObject::from_retained)
            .collect();
        let array = NSArray::from_vec(objs);
        // SAFETY: every element is an NSPasteboardItem, which conforms to
        // NSPasteboardWriting; the array is retained for the call.
        let ok = unsafe { pb.writeObjects(&array) };
        if !ok {
            return Err(InjectError::Clipboard(
                "NSPasteboard writeObjects returned NO".into(),
            ));
        }
    }
    // SAFETY: plain getter.
    Ok(unsafe { pb.changeCount() })
}

fn set_data(item: &NSPasteboardItem, ty: &NSPasteboardType, bytes: &[u8]) -> bool {
    let data = NSData::with_bytes(bytes);
    // SAFETY: `item` is a fresh, retained NSPasteboardItem; `data` and
    // `ty` are retained for the duration of the call.
    unsafe { item.setData_forType(&data, ty) }
}

fn text_item(text: &str, transient: bool) -> Result<Retained<NSPasteboardItem>, InjectError> {
    // SAFETY: `new` allocates + inits an empty item; no preconditions.
    let item = unsafe { NSPasteboardItem::new() };
    let ns_text = NSString::from_str(text);
    // SAFETY: `NSPasteboardTypeString` is an AppKit-provided constant
    // NSString, valid for the process lifetime.
    let ok = unsafe { item.setString_forType(&ns_text, NSPasteboardTypeString) };
    if !ok {
        return Err(InjectError::Clipboard(
            "NSPasteboardItem setString returned NO".into(),
        ));
    }
    if transient {
        for marker in [TRANSIENT_TYPE, AUTO_GENERATED_TYPE] {
            // Markers are presence-only; empty data is the convention.
            set_data(&item, &NSString::from_str(marker), &[]);
        }
    }
    Ok(item)
}

/// Write `text` tagged as transient/auto-generated (skipped by clipboard
/// managers). Returns the `changeCount` right after the write.
pub fn write_transient(text: &str) -> Result<isize, InjectError> {
    autoreleasepool(|_| write_items(vec![text_item(text, true)?]))
}

/// Write `text` as a normal, user-visible clipboard entry. Used when the
/// transcript is intentionally left on the clipboard for a manual ⌘V.
pub fn write_plain(text: &str) -> Result<(), InjectError> {
    autoreleasepool(|_| write_items(vec![text_item(text, false)?]).map(|_| ()))
}

/// Put `snap` back on the pasteboard if `changeCount` still equals
/// `recorded_change_count`. Returns whether a restore happened.
pub fn restore_if_unchanged(
    snap: PasteboardSnapshot,
    recorded_change_count: isize,
) -> Result<bool, InjectError> {
    autoreleasepool(|_| {
        let pb = general();
        // SAFETY: plain getter.
        let current = unsafe { pb.changeCount() };
        if !should_restore(recorded_change_count, current) {
            return Ok(false);
        }
        let items = snap
            .items
            .iter()
            .map(|reps| {
                // SAFETY: `new` allocates + inits an empty item.
                let item = unsafe { NSPasteboardItem::new() };
                for (ty, bytes) in reps {
                    set_data(&item, &NSString::from_str(ty), bytes);
                }
                item
            })
            .collect();
        write_items(items)?;
        Ok(true)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn restores_only_when_change_count_unchanged() {
        assert!(should_restore(42, 42));
        assert!(!should_restore(42, 43));
        assert!(!should_restore(42, 41));
    }

    #[test]
    #[ignore = "mutates the real pasteboard"]
    fn round_trip_restores_prior_contents() {
        let marker = "dictateflow-pasteboard-test-marker";
        write_plain(marker).expect("seed");
        let snap = snapshot();
        assert!(!snap.items.is_empty());
        let cc = write_transient("replacement").expect("write");
        assert!(restore_if_unchanged(snap.clone(), cc).expect("restore"));
        assert_eq!(snapshot(), snap);
    }
}
